import assert from "node:assert/strict";
import { MessageChannel, receiveMessageOnPort } from "node:worker_threads";

const deadline = setTimeout(() => { throw new Error("close events did not finish"); }, 1000);
const { port1, port2 } = new MessageChannel();
const messages: unknown[] = [];
const closes = [0, 0];
const callbacks = [0, 0];
port1.on("message", (value) => messages.push(value));
port2.on("message", (value) => messages.push(value));
port1.on("close", () => closes[0]++);
port2.on("close", () => closes[1]++);
const closed = Promise.all([port1, port2].map((port) => new Promise<void>((resolve) => port.once("close", resolve))));
port1.close(() => callbacks[0]++);
port1.close(() => callbacks[1]++);
port2.postMessage("after-local-close");
assert.deepEqual(receiveMessageOnPort(port1), { message: "after-local-close" });
console.log("peer posts before close notification");
await closed;
assert.deepEqual(closes, [1, 1]);
assert.deepEqual(callbacks, [1, 1]);
assert.deepEqual(messages, []);
assert.equal(port1.hasRef(), false);
assert.equal(port2.hasRef(), false);
port2.postMessage("after-disentangle");
assert.equal(receiveMessageOnPort(port1), undefined);
console.log("both endpoints close once and disentangle");
let lateCallbacks = 0;
port1.close(() => lateCallbacks++);
port2.close(() => lateCallbacks++);
await new Promise<void>((resolve) => setImmediate(resolve));
assert.equal(lateCallbacks, 0);
assert.deepEqual(closes, [1, 1]);
clearTimeout(deadline);
console.log("repeated close does not emit another event or callback");
